from collections import deque

def grid_bfs(grid, start, goal):              # 0 = open, 1 = wall
    rows, cols = len(grid), len(grid[0])
    q, seen = deque([(start, 0)]), {start}
    while q:
        (r, c), d = q.popleft()
        if (r, c) == goal:
            return d                           # first hit = fewest steps
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            inside = 0 <= nr < rows and 0 <= nc < cols
            if inside and grid[nr][nc] == 0 and (nr, nc) not in seen:
                seen.add((nr, nc))             # mark on push: queued once
                q.append(((nr, nc), d + 1))
    return -1                                  # unreachable

def count_components(n, adj):
    seen, count = set(), 0
    for s in range(n):
        if s not in seen:                      # new component: flood it
            count += 1
            seen.add(s)
            stack = [s]                        # explicit stack: no recursion limit
            while stack:
                for nb in adj[stack.pop()]:
                    if nb not in seen:
                        seen.add(nb)
                        stack.append(nb)
    return count
